    required this.callId,
    required this.name,
    this.args,
  });

  final String callId;

  final String name;

  final Object? args;

  factory ToolCall.fromJson(Map<String, Object?> json) => ToolCall(
        callId: json['call_id'] as String,
        name: json['name'] as String,
        args: json['args'],
      );

  Map<String, Object?> toJson() => {
        'call_id': callId,
        'name': name,
        'args': args,
      };
}

/// A tool an agent may call: what the model (or an external harness) sees.
class ToolInfo {
  const ToolInfo({
    required this.name,
    required this.description,
    this.parameters,
  });

  final String name;

  final String description;

  /// JSON schema of the arguments object.
  final Object? parameters;

  factory ToolInfo.fromJson(Map<String, Object?> json) => ToolInfo(
        name: json['name'] as String,
        description: json['description'] as String,
        parameters: json['parameters'],
      );

  Map<String, Object?> toJson() => {
        'name': name,
        'description': description,
        'parameters': parameters,
      };
}

enum TurnState {
  idle('idle'),
  running('running'),
  /// Waiting for a model slot.
  waiting('waiting'),
  /// Blocked on a recipe approval.
  awaitingApproval('awaiting_approval');

  const TurnState(this.wire);
  final String wire;

  static TurnState fromJson(Object? json) =>
      values.firstWhere((v) => v.wire == json, orElse: () => throw FormatException('unknown TurnState: $json'));

  String toJson() => wire;
}

/// A piece of work in a pipeline (`site://<pipeline>/<work>/index.md`, `type: work`).
class WorkSummary {
  const WorkSummary({
    required this.url,
    required this.pipeline,
    required this.title,
    this.status,
    this.stages = const [],
    this.project,
  });

  final String url;

  /// The pipeline's site.
  final String pipeline;

  final String title;

  /// Where it is: the stage it is at and its state (`01 spec · waiting`), or `done`.
  final String? status;

  /// Its stages in order, with their state.
  final List<StageState> stages;

  /// The project it links (`~/Projects/game`).
  final String? project;

  factory WorkSummary.fromJson(Map<String, Object?> json) => WorkSummary(
        url: json['url'] as String,
        pipeline: json['pipeline'] as String,
        title: json['title'] as String,
        status: json['status'] == null ? null : json['status'] as String,
        stages: json['stages'] == null ? const [] : (json['stages'] as List).map((e) => StageState.fromJson(e as Map<String, Object?>)).toList(),
        project: json['project'] == null ? null : json['project'] as String,
      );

  Map<String, Object?> toJson() => {
        'url': url,
        'pipeline': pipeline,
        'title': title,
        if (status != null) 'status': status,
        if (stages.isNotEmpty) 'stages': stages.map((e) => e.toJson()).toList(),
        if (project != null) 'project': project,
      };
}

enum WorkerState {
  starting('starting'),
  running('running'),
  done('done'),
  failed('failed'),
  /// Stopped before finishing, to be resumed later (a usage limit was hit).
  paused('paused');

  const WorkerState(this.wire);
  final String wire;

  static WorkerState fromJson(Object? json) =>
      values.firstWhere((v) => v.wire == json, orElse: () => throw FormatException('unknown WorkerState: $json'));

  String toJson() => wire;
}
